 FOR fn IN SELECT oid FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN
 ('get_home_postcard_request','cancel_home_postcard_request','get_home_postcard_current_status','claim_home_postcard_current_dispatch','record_home_postcard_current_dispatch','begin_home_postcard_request','home_postcard_request_work','home_postcard_confirmed_address') LOOP
 IF has_function_privilege('authenticated',fn.oid,'EXECUTE') OR has_function_privilege('anon',fn.oid,'EXECUTE')
 OR NOT has_function_privilege('service_role',fn.oid,'EXECUTE') THEN RAISE EXCEPTION 'Postal worker function is exposed'; END IF;
 END LOOP;
END $$;

